'use strict';

const $ = (s, el = document) => el.querySelector(s);
const t = (en, zh) => state.lang === 'zh' ? zh : en;
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storeKey = 'carepath-demo-v1';
let cached = {};
try { cached = JSON.parse(localStorage.getItem(storeKey) || '{}'); } catch (_) {}
const state = {
  lang: cached.lang === 'zh' ? 'zh' : 'en', large: !!cached.large,
  screen: cached.screen || 'welcome', doc: cached.doc || '', confirmed: !!cached.confirmed,
  name: cached.name || 'Mary', household: cached.household || '', contact: cached.contact || 'phone',
  income: cached.income || '', consent: !!cached.consent, prepared: !!cached.prepared,
  handoff: !!cached.handoff, handoffSnapshot: cached.handoffSnapshot || null, partnerStatus: cached.partnerStatus || 'needs-review',
  partnerFilter: 'all', search: '', selectedCase: '', reviewed: false, dsError: false
};
const app = $('#app');
const dialog = $('#dialog');
let dialogKind = '';
let priorFocus = null;
let busyTimer;

function save() {
  // Store only scenario selections and display preferences; no uploaded files or free-form messages.
  const {lang,large,screen,doc,confirmed,household,contact,income,consent,prepared,handoff,handoffSnapshot,partnerStatus} = state;
  try { localStorage.setItem(storeKey, JSON.stringify({lang,large,screen,doc,confirmed,household,contact,income,consent,prepared,handoff,handoffSnapshot,partnerStatus})); } catch (_) {}
}
function icon(name, size = 20) {
  const paths = {
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
    check:'<path d="m5 12 4 4L19 6"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>',
    file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM14 3v6h6M8 14h8M8 17h5"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
    person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
    chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/><path d="M7 10h9M7 14h5"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.4 1.6c-1.2.8-1.9 1.4-1.9 3.4M12 17h.01"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    folder:'<path d="M3 6h7l2 3h9v11H3Z"/>',
    sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',
    leaf:'<path d="M20 3C9 2 2 8 5 16c8 3 15-3 15-13ZM4 21 16 8"/>'
  };
  return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${paths[name] || paths.file}</svg>`;
}
function mark() {
  return '<svg aria-hidden="true" width="32" height="32" viewBox="0 0 40 40" fill="none"><path d="M8 32V18a12 12 0 0 1 24 0v14M15 32V18a5 5 0 0 1 10 0v14M3 32h15m4 0h15" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>';
}
function brand(link = '#case') { return `<a class="brand" href="${link}" aria-label="CarePath home">${mark()}CarePath</a>`; }
function button(label, action, style = 'primary', attrs = '', ico = '') {
  return `<button class="btn ${style}" data-action="${action}" ${attrs}>${label}${ico ? icon(ico,18) : ''}</button>`;
}
function pill(label, kind = 'green') { return `<span class="pill ${kind}">${esc(label)}</span>`; }
function route() { const key=location.hash.slice(1).split('/')[0]; if(key.startsWith('ds-'))return 'system'; return ['case','prototype','partners','system'].includes(key) ? key : 'case'; }
function header(active) {
  return `<header class="topbar"><div class="shell topbar-inner"><div class="row">${brand()}<span class="project-tag">INDEPENDENT CONCEPT<br>PRODUCT DESIGN · 2026</span></div><nav class="global-nav" aria-label="Main navigation">
    ${[['case',t('Case study','作品集案例')],['prototype',t('Member prototype','会员端原型')],['partners',t('Partner workspace','合作方工作台')],['system',t('Design system','设计系统')]].map(([r,label])=>`<a href="#${r}" ${active===r?'class="active" aria-current="page"':''}>${label}</a>`).join('')}
    </nav><div class="utility">${pill(t('Concept / v1.0','概念 / v1.0'),'dot')}<button class="lang" data-action="lang" aria-label="${t('Switch to Chinese','切换为英文')}">${t('中 / EN','EN / 中')}</button></div></div></header>`;
}
function footer() { return `<footer class="footer"><span>CarePath / ${t('Independent product design exploration','独立产品设计探索')} · 2026</span><span><a href="#prototype">${t('Explore prototype','体验原型')}</a><a href="#system">${t('View system','查看设计系统')}</a></span></footer>`; }
function miniApp() {
  return `<div class="mini-app"><div class="row mini-brand">${mark()}CarePath</div><span class="eyebrow">${t('One step at a time','每次，只走一步')}</span><h3>${t('Good morning, Mary.','早上好，Mary。')}</h3><p>${t('Let’s make sense of your letter.','一起读懂你收到的信。')}</p><div class="mini-task"><span class="mini-check">${icon('check',15)}</span><div><strong class="small">${t('Your letter, made clearer','这封信，说清楚了')}</strong><p>${t('A plain-language explanation is ready.','白话解释已经准备好了。')}</p></div></div><div class="mini-button">${t('See what to do next','看看下一步怎么做')}${icon('arrow',15)}</div></div>`;
}
function letter(compact = false) {
  return `<div class="paper-letter ${compact?'compact':''}"><div class="row between"><span class="eyebrow">SAMPLE DOCUMENT</span>${icon('file',18)}</div><h4 style="margin-top:18px">Riverside Community Hospital</h4><p class="small">${t('Patient account statement','患者账户账单')}<br>Mary Thompson · Nov 12, 2026</p><div class="letter-rule"></div><p>${t('Our records show a remaining patient responsibility after insurance processing. Please contact our billing office with any questions about your statement.','保险处理后，您的患者账户仍有待付余额。如对账单有疑问，请联系账务办公室。')}</p><div class="letter-amount"><div class="row between"><span>${t('Patient responsibility','患者待付金额')}</span><strong>$186.00</strong></div></div><p class="small" style="margin-top:20px">${t('For assistance, contact the patient billing team.','如需协助，请联系患者账务团队。')}</p><div class="letter-rule"></div><span class="eyebrow">${t('Fictional hospital · Not a real bill','虚构医院 · 非真实账单')}</span></div>`;
}

function unclearLetter(){
  return `<div class="paper-letter"><span class="eyebrow">SAMPLE DOCUMENT / LOW CLARITY</span><h4 style="margin-top:20px">Riverside Community Hospital</h4><p style="margin-top:26px">Mary Thompson</p><div class="letter-rule"></div><p style="filter:blur(2px);user-select:none" aria-hidden="true">Patient statement<br>Reference number unclear<br>Remaining amount unreadable</p><div class="callout warning"><strong>${t('Amount: unable to read','金额：无法辨认')}</strong><p>${t('This sample needs human review.','此示例需要人工复核。')}</p></div><p class="small muted" style="margin-top:20px">${t('Fictional sample; intentionally unclear.','刻意模糊的虚构示例。')}</p></div>`;
}

function casePage() {
  return `${header('case')}<main id="main" tabindex="-1" class="shell">
    <section class="case-hero" aria-labelledby="case-title"><div class="row between wrap"><span class="eyebrow">01 / ${t('Healthcare · AI interaction · Accessible design','医疗服务 · AI 交互 · 无障碍设计')}</span><span class="eyebrow">${t('PROTOTYPE BUILT · RESEARCH PLANNED','原型已实现 · 真实研究待开展')}</span></div>
    <div class="hero-grid"><div class="hero-copy"><h1 id="case-title">${t('A little clarity.<br><em>A lot of relief.</em>','多一点清晰。<br><em>少一份担忧。</em>')}</h1><p class="intro">${t('Helping older adults turn confusing medical paperwork into a next step they understand—and choose.','帮助老年人读懂复杂的医疗费用文件，理解下一步，并自主决定如何行动。')}</p><div class="hero-actions"><a class="btn primary" href="#prototype">${t('Try the prototype','体验交互原型')}${icon('arrow',18)}</a><a class="btn text" href="#overview">${t('Read the story','阅读设计案例')}</a></div></div>
    <div class="hero-art" aria-label="CarePath member interface preview"><span class="art-caption">A CLEARER PATH TO CARE</span>${miniApp()}<div class="floating-note"><span class="row">${icon('person',18)}<strong>${t('A person, when you need one.','需要时，真人就在身边。')}</strong></span><span class="muted">${t('Human support is always in reach.','始终可见的人工协助入口。')}</span></div><svg class="path-lines" viewBox="0 0 500 110" fill="none"><path d="M-30 100C150-80 280 190 540-25M-30 125C150-55 280 215 540 0M-30 150C150-30 280 240 540 25" stroke="#6c826b" stroke-width="1"/></svg></div></div>
    <div class="project-meta"><div><span class="eyebrow">${t('Contribution explored','本项目覆盖')}</span><strong>Product strategy, UX / UI, prototyping</strong></div><div><span class="eyebrow">${t('Designed for','目标用户')}</span><strong>${t('Older adults & support staff','老年用户与协助人员')}</strong></div><div><span class="eyebrow">${t('Deliverables','交付内容')}</span><strong>${t('Member flow + partner workflow','会员流程 + 合作方工作台')}</strong></div><div><span class="eyebrow">${t('Project status','项目状态')}</span><strong>${t('Independent concept · v1.0','独立概念项目 · v1.0')}</strong></div></div></section>
    <nav class="case-toc" aria-label="Case study sections">${[['overview',t('01 Overview','01 项目概览')],['principles',t('02 Design decisions','02 设计决策')],['workflow',t('03 The experience','03 交互体验')],['safety',t('04 Human + AI','04 人与 AI')],['foundations',t('05 The system','05 设计系统')],['research',t('06 What comes next','06 研究与下一步')]].map(([id,n])=>`<a href="#${id}">${n}</a>`).join('')}</nav>
    <section class="case-section" id="overview"><div class="section-grid"><div class="section-label eyebrow">01 / ${t('The starting point','问题起点')}</div><div class="section-body"><h2 class="statement">${t('The hard part isn’t uploading a letter.<br>It’s knowing what it means.','困难不在于上传文件，<br>而在于理解它的意思。')}</h2><p>${t('CarePath explores a specific moment: an older adult receives an unfamiliar medical statement and needs help understanding it, gathering information, and preparing a conversation about assistance.','CarePath 聚焦一个具体时刻：一位老人收到陌生的医疗费用文件，需要理解内容、整理材料，并为咨询费用援助做好准备。')}</p><p>${t('The opportunity is to make progress visible without asking someone to trust an opaque AI answer. A document, its explanation, and a clear next action belong together.','设计机会是让进展可见，而不是要求用户相信一个不透明的 AI 答案。原始文件、白话解释与明确的下一步应该彼此对应。')}</p><div class="problem-band"><div><span class="eyebrow">${t('Initial hypothesis','初始假设')}</span><h3>${t('Uncertainty interrupts progress.','不确定，会打断行动。')}</h3><p>${t('Unfamiliar language, missing documents, and fear of making a mistake may stop people before they ask for help. This needs direct research.','陌生术语、材料缺失与害怕出错，可能让用户放弃求助。这一判断仍需要真实研究。')}</p></div><div><span class="eyebrow">${t('Design question','设计挑战')}</span><h3>${t('How do we support confidence without taking away control?','如何增强信心，同时保留自主权？')}</h3><p>${t('Explain first. Ask one understandable question at a time. Make review and human help part of the main flow.','先解释，再提问。一次完成一个可理解的任务。把核对与人工协助放进主流程。')}</p></div></div></div></div></section>
    <section class="case-section" id="principles"><div class="section-grid"><div class="section-label eyebrow">02 / ${t('Design decisions','设计决策')}</div><div class="section-body"><h2>${t('Calm is a product decision.','安心，来自明确的设计选择。')}</h2><p>${t('An older audience is not a single persona. Reading ability, confidence, device use, and family support vary. These choices are hypotheses to test—not assumptions about everyone over 65.','老年人并不是单一画像。阅读能力、信心、设备习惯与家庭支持各不相同。以下设计是待验证的选择，而非对所有 65 岁以上用户的推断。')}</p><div class="design-principles">${[
      [t('Guide, don’t overwhelm.','引导，而非堆砌。'),t('A five-part stepper, one task per screen, and an explicit next action reduce the need to remember what comes next.','五步进度、每屏一个主要任务和明确的下一步，降低用户记忆流程的负担。')],
      [t('Show the evidence.','让依据可见。'),t('Keep the sample document beside its explanation. Distinguish extracted facts, unknowns, and suggestions. Never display a made-up confidence score.','将原文和解释并置。区分提取事实、未知信息与建议，不使用虚构的 AI 置信度。')],
      [t('Make help ordinary.','让求助成为正常选项。'),t('A persistent, text-labelled help action preserves context. A review request carries the document, confirmed information, and the open question.','始终显示文字求助入口。交接时保留文件、已确认信息和待解答问题。')],
      [t('Ask before acting.','行动前，先征得同意。'),t('People review their details and explicitly authorize a scoped handoff. Preparing a checklist never implies submitting an application.','用户核对后，对具体共享范围进行授权。准备清单，不意味着提交申请。')]
    ].map(([h,p])=>`<div class="principle"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></div></section>
    <section class="case-section" id="workflow"><div class="section-grid"><div class="section-label eyebrow">03 / ${t('The experience','核心体验')}</div><div class="section-body"><h2>${t('A path, not a blank chat box.','一条路径，而非空白聊天框。')}</h2><p>${t('The member flow moves from understanding to preparation. The AI helper supports the task; it does not replace the structure or make eligibility decisions.','会员流程从理解文件出发，最终准备下一步材料。AI 辅助具体任务，不替代流程结构，也不进行资格判定。')}</p><div class="journey">${[
      [t('Add a letter','选择文件'),t('Choose a fictional clear or hard-to-read sample.','选择清晰或模糊的虚构示例。')],
      [t('Understand','理解内容'),t('Compare the explanation with its source.','对照白话解释与原文。')],
      [t('Add details','补充信息'),t('Answer a few small, recoverable questions.','回答可返回修改的小问题。')],
      [t('Review','核对授权'),t('Check details and choose what to share.','核对信息，决定共享范围。')],
      [t('Prepare','准备下一步'),t('Get a checklist or request a person.','获得清单或请求人工协助。')]
    ].map(([h,p],i)=>`<div class="journey-step"><span class="num">0${i+1}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><div class="human-branch">${icon('person',17)}${t('At any step: pause, go back, or ask a person—with context intact.','任何步骤：暂停、返回，或带着已有上下文求助真人。')}</div>
    <div class="showcase"><div class="showcase-bar"><span class="eyebrow">${t('KEY SCREEN / UNDERSTAND','关键界面 / 理解文件')}</span>${pill(t('Source-linked explanation','对应原文的解释'))}</div><div class="showcase-columns">${letter(true)}<div class="explanation"><span class="eyebrow">${t('In plain language','换成日常语言')}</span><h3>${t('This letter shows an amount left to pay.','这封信显示仍有待付金额。')}</h3><p>${t('The sample statement lists $186 after insurance processing. The letter does not tell us whether assistance is available.','示例账单显示保险处理后待付 $186。文件并没有说明是否可获得费用援助。')}</p><span class="source-tag">${t('SOURCE: “PATIENT RESPONSIBILITY”','依据：“PATIENT RESPONSIBILITY” 一行')}</span><div class="callout"><strong class="small">${t('You can ask about help.','你可以咨询是否有援助。')}</strong><p>${t('We can help you prepare questions for the billing team.','我们可以协助准备向账务团队提出的问题。')}</p></div></div></div></div>
    <div class="decision"><span class="eyebrow">${t('Why this matters','为什么这样设计')}</span><p>${t('An open-ended chat asks people to formulate the right question. A structured explanation gives them a starting point and something concrete to verify.','开放聊天要求用户先提出正确问题；结构化解释先提供起点，并给用户具体可核对的依据。')}</p></div><div class="hero-actions"><a class="btn primary" href="#prototype">${t('Walk through the member flow','走一遍完整会员流程')}${icon('arrow',18)}</a></div></div></div></section>
    <section class="case-section" id="safety"><div class="section-grid"><div class="section-label eyebrow">04 / ${t('Human + AI','人与 AI 的边界')}</div><div class="section-body"><h2>${t('Trust needs an exit ramp.','可信任的流程，要能随时交接。')}</h2><p>${t('The prototype includes the difficult states: unreadable content, unknown information, missing consent, and a person requesting help. The partner view continues the same case rather than starting over.','原型包含关键异常状态：文件看不清、信息不确定、尚未授权、用户主动求助。合作方可以延续同一案例，而不必让用户从头讲起。')}</p><table class="evidence-table"><thead><tr><th>${t('Trigger','触发条件')}</th><th>${t('Product response','产品响应')}</th><th>${t('Human control','用户控制')}</th></tr></thead><tbody><tr><td>${t('Hard-to-read document','文件模糊')}</td><td>${t('Stop extraction. Flag the unknown amount.','停止提取，标明金额无法确认。')}</td><td>${t('Replace sample or request review.','更换示例或请求人工复核。')}</td></tr><tr><td>${t('Information unavailable','信息暂时未知')}</td><td>${t('Keep “not sure” as a valid answer.','允许选择“不确定”。')}</td><td>${t('Continue to prepare questions.','继续整理待咨询的问题。')}</td></tr><tr><td>${t('No sharing permission','尚未授权共享')}</td><td>${t('Do not create a partner case.','不创建合作方案例。')}</td><td>${t('Review scope, cancel, or agree.','查看范围、取消或同意。')}</td></tr><tr><td>${t('Request a person','请求真人')}</td><td>${t('Create a simulated review request with context.','创建附带上下文的模拟复核请求。')}</td><td>${t('View, withdraw, or re-request.','查看、撤回或重新请求。')}</td></tr></tbody></table><div class="boundary-grid"><div><h3>${t('AI may assist','AI 可以辅助')}</h3><p>${t('Explain a sample, organize confirmed details, suggest questions, and prepare a checklist.','解释示例、整理已确认信息、建议咨询问题、准备清单。')}</p></div><div><h3>${t('People decide','人来决定')}</h3><p>${t('Confirm facts, authorize sharing, verify assistance options, and handle any real application.','确认事实、授权共享、核实援助选项，以及办理真实申请。')}</p></div></div><a class="btn text" href="#partners" style="margin-top:22px">${t('Explore the partner handoff','体验合作方交接')}${icon('arrow',18)}</a></div></div></section>
    <section class="case-section" id="foundations"><div class="section-grid"><div class="section-label eyebrow">05 / ${t('Design foundations','设计基础')}</div><div class="section-body"><h2>${t('One system. Two rhythms.','一套系统，两种工作节奏。')}</h2><p>${t('The member experience uses generous space and one clear next action. The partner workspace uses denser tables and review history. Shared semantic tokens keep status, permission, and error language consistent.','会员端以留白和单一主要操作降低负担；合作方端以更紧凑的表格和复核历史提高处理效率。共享语义令牌，统一状态、授权和错误表达。')}</p><div class="system-preview"><div><span class="eyebrow">${t('Color / natural, not clinical','配色 / 温暖且可信')}</span><div class="swatches"><div class="swatch pine"><span>#21483E</span></div><div class="swatch sage"><span>#E6EDE2</span></div><div class="swatch paper"><span>#F7F5EF</span></div><div class="swatch orange"><span>#A34D30</span></div></div><p class="small muted">${t('Pine for action. Sage for context. Clay for attention. Meaning always includes a text label.','松绿承载行动，浅绿提供上下文，陶色提示注意；所有语义状态均配文字。')}</p></div><div><span class="eyebrow">${t('Type / a human voice','字体 / 有温度的声音')}</span><p class="type-sample">${t('A little more clarity.','把复杂，说清楚。')}</p><p class="small muted">Libre Caslon Display + DM Sans<br>${t('Editorial headings; readable product text.','编辑式标题，清晰易读的产品正文。')}</p></div></div><div class="metric-row"><div class="metric"><strong>48 px</strong><p>${t('Minimum primary target','主要触控区域下限')}</p></div><div class="metric"><strong>18 px</strong><p>${t('Default body text + larger-text mode','默认正文，另设大字模式')}</p></div><div class="metric"><strong>4 / 8</strong><p>${t('Base spacing rhythm','基础间距节奏')}</p></div></div><a class="btn secondary" href="#system">${t('Explore components & states','体验组件与状态')}${icon('arrow',18)}</a></div></div></section>
    <section class="case-section" id="research"><div class="section-grid"><div class="section-label eyebrow">06 / ${t('Evidence & next steps','证据与下一步')}</div><div class="section-body"><h2>${t('Built to be tested.<br>Not presented as proven.','为验证而构建，<br>不把假设当成果。')}</h2><div class="research-note"><strong>${t('Research status: planned, not completed.','研究状态：已规划，尚未完成。')}</strong>${t('This independent concept uses fictional people, documents, and scripted AI responses. No user interviews, usability results, or business impact are claimed.','本独立概念项目使用虚构人物、文件与脚本化 AI 回复。尚无真实访谈、用户测试结果或业务成效。')}</div><p>${t('The next phase should test whether the structure helps people understand and act—not simply whether they like the visual design. Recruit 3–5 older adults or caregivers with varied digital confidence, and record the limits of that sample.','下一阶段应验证流程是否帮助用户理解并行动，而不只是询问视觉喜好。计划招募 3–5 位数字熟悉度不同的老年人或照护者，并如实记录样本局限。')}</p><table class="evidence-table"><thead><tr><th>${t('Test task','测试任务')}</th><th>${t('What to observe','观察内容')}</th></tr></thead><tbody><tr><td>${t('Explain what the sample letter says.','用自己的话复述示例文件。')}</td><td>${t('Distinguishes the amount from assistance eligibility.','能否区分账单金额与援助资格。')}</td></tr><tr><td>${t('Find and correct an answer.','找到并修改一个回答。')}</td><td>${t('Completion, recovery, and requests for help.','任务完成、错误恢复与求助情况。')}</td></tr><tr><td>${t('Request a person for the unclear letter.','针对模糊文件请求真人协助。')}</td><td>${t('Understands what is shared and how to cancel.','是否理解共享范围及撤回方法。')}</td></tr></tbody></table><div class="decision"><span class="eyebrow">${t('Planned evaluation','拟定评估指标')}</span><p>${t('Task completion, misunderstandings, help requests, and confidence before / after the task. Establish a baseline before setting success thresholds. After testing, add evidence-linked iterations instead of invented before-and-after results.','任务完成情况、误解点、求助次数与前后信心变化。先建立基线，再确定成功标准。测试后补充对应证据的迭代，不虚构前后对比结果。')}</p></div>${button(t('Download research plan','下载研究计划'),'research-download','text','','download')}</div></div></section>
    <section class="case-end"><div><span class="eyebrow" style="color:#c6d4c7">${t('EXPLORE THE WORK','探索实际体验')}</span><h2 style="margin-top:14px">${t('Follow Mary’s next step.','陪 Mary 走出下一步。')}</h2><p>${t('A complete flow, including the moments that need a person.','完整的任务流程，也包含需要真人的时刻。')}</p></div><a class="btn light" href="#prototype">${t('Open the prototype','打开交互原型')}${icon('arrow',18)}</a></section>${footer()}</main>`;
}

const stepKeys = ['document','understand','details','review','next'];
function stepNames(){ return [t('Your letter','你的文件'),t('Understand','理解内容'),t('Your details','补充信息'),t('Review','核对信息'),t('Next steps','下一步')]; }
function productHeader(partner = false) {
  return `<div class="demo-ribbon">${t('INTERACTIVE CONCEPT · Fictional sample data. No real documents, eligibility decisions, or applications.','交互式概念原型 · 使用虚构示例，不处理真实文件、不判断资格、不提交申请。')}</div><div class="product-header"><div class="product-header-inner">${brand(partner?'#partners':'#prototype')}<div class="product-header-right">${partner?`<span class="eyebrow">${t('PARTNER WORKSPACE','合作方工作台')}</span>`:`<button class="font-control" data-action="font" aria-pressed="${state.large}">${state.large?t('Aa  Standard text','Aa  标准字号'):t('Aa  Larger text','Aa  更大字号')}</button>`}<span class="small muted">${t('Demo session','示例会话')}</span><span class="avatar">${partner?'AS':'MT'}</span></div></div>${!partner?`<div class="mobile-support">${button(t('Ask a person','请真人帮忙'),'human','text','','person')}${button(t('Save & pause','保存并暂停'),'pause','text')}</div>`:''}</div>`;
}
function memberSidebar(){
  let index = stepKeys.indexOf(state.screen); if(index<0) index = 0;
  return `<aside class="member-sidebar"><span class="eyebrow">${t('Your path to support','通往援助的路径')}</span><ol class="step-list" aria-label="${t('Application preparation steps','申请准备步骤')}">${stepNames().map((n,i)=>`<li class="step-item ${i<index?'done':i===index?'current':''}" ${i===index?'aria-current="step"':''}><span class="step-number">${i<index?icon('check',14):i+1}</span><p>${n}</p></li>`).join('')}</ol><div class="sidebar-help"><span class="icon-mark">${icon('person',22)}</span><p>${t('You don’t have to do this alone.','你不必独自完成。')}</p>${button(t('Ask a person','请真人帮忙'),'human','text')}${button(t('Save & pause','保存并暂停'),'pause','text')}</div></aside>`;
}
function memberActions(back, nextLabel, action = 'continue', disabled = false){
  return `<div class="member-actions">${button(t('Back','返回'),back,'secondary','','back')}${button(nextLabel,action,'primary',disabled?'disabled':'','arrow')}</div>`;
}
function memberWelcome(){
  return `<span class="eyebrow">${t('WELCOME / YOUR SUPPORT, AT YOUR PACE','欢迎 / 按你的节奏，获得支持')}</span><h1>${t('Good morning, Mary.','早上好，Mary。')}</h1><p class="lead">${t('Medical paperwork can be confusing. Let’s take it one step at a time.','医疗文件可能很难懂。我们一起，一次完成一步。')}</p><div class="member-content"><div class="welcome-panel"><div><span class="icon-mark">${icon('file',24)}</span><h2>${t('Let’s start with your letter.','先从你收到的信开始。')}</h2><p>${t('We’ll explain what it says, help you gather details, and make a plan for asking about support.','我们会解释内容、协助整理信息，并为你咨询援助做好准备。')}</p>${button(t('Start with a sample letter','从示例文件开始'),'start','primary','','arrow')}</div><div class="journey-illustration" aria-hidden="true"><svg width="150" height="180" viewBox="0 0 150 180" fill="none"><path d="M20 160V70a55 55 0 0 1 110 0v90M40 160V70a35 35 0 0 1 70 0v90M60 160V70a15 15 0 0 1 30 0v90" stroke="#7b9478" stroke-width="1.5"/><rect x="35" y="70" width="85" height="70" rx="5" fill="#fffefb" stroke="#7b9478"/><path d="M52 90h50M52 101h40M52 112h30" stroke="#8fa28b"/><circle cx="111" cy="133" r="18" fill="#21483e"/><path d="m103 133 5 5 10-11" stroke="#fffefb" stroke-width="2"/></svg></div></div><div class="welcome-bottom">${icon('shield',19)}${t('You choose what to share. Nothing is submitted automatically.','你决定共享什么。系统不会自动提交任何内容。')}</div>${state.doc?`<div class="white-panel" style="margin-top:24px"><span class="eyebrow">${t('YOUR DEMO DRAFT','你的示例草稿')}</span><p style="margin-top:10px">${t('A sample letter is already in your draft.','草稿中已有一份示例文件。')}</p>${button(t('Continue draft','继续草稿'),'resume','text','','arrow')}</div>`:''}</div>`;
}
function memberDocument(){
  return `<span class="eyebrow">${t('STEP 1 OF 5 / YOUR LETTER','第 1 步，共 5 步 / 你的文件')}</span><h1>${t('What would you like help with?','你想了解哪份文件？')}</h1><p class="lead">${t('Choose a fictional letter to explore. In this demo, files stay out of the experience.','选择虚构文件体验流程。此原型不会接收或上传你的真实文件。')}</p><div class="member-content"><div class="upload-options"><button class="doc-choice ${state.doc==='clear'?'selected':''}" data-action="select-clear" aria-pressed="${state.doc==='clear'}"><span class="icon-mark">${icon('file',24)}</span><strong>${t('A clear sample letter','清晰的示例文件')}</strong><p>${t('A hospital statement with a readable amount and contact information.','账单金额与联系说明均可辨认的医院账单。')}</p>${pill(t('Explore the main flow','体验主流程'))}</button><button class="doc-choice ${state.doc==='unclear'?'selected':''}" data-action="select-unclear" aria-pressed="${state.doc==='unclear'}"><span class="icon-mark">${icon('eye',24)}</span><strong>${t('A hard-to-read letter','难以辨认的示例文件')}</strong><p>${t('Some text is unclear. See how we ask for a person instead of guessing.','部分文字模糊，体验系统如何交由真人复核，而非猜测。')}</p>${pill(t('Explore a recovery path','体验异常恢复'),'orange')}</button></div><div class="privacy-line">${icon('shield',18)}<span>${t('Only fictional samples are available. Please don’t enter real medical or financial information.','仅支持虚构示例。请勿输入真实医疗或财务信息。')}</span></div></div>${memberActions('welcome',t('Explain this letter','解释这份文件'),'explain',!state.doc)}`;
}
function memberUnderstand(){
  const unclear=state.doc==='unclear';
  return `<span class="eyebrow">${t('STEP 2 OF 5 / UNDERSTAND','第 2 步，共 5 步 / 理解内容')}</span><h1>${unclear?t('Let’s check this together.','这份文件，需要一起核实。'):t('Here’s what your letter says.','这封信的意思是……')}</h1><p class="lead">${unclear?t('Some of this sample is hard to read. We won’t guess the missing details.','示例中的部分内容难以辨认，我们不会猜测缺失信息。'):t('A plain-language explanation, with the original right beside it.','将文件换成日常语言，并在旁边保留原文供你核对。')}</p><div class="member-content"><div class="doc-detail-grid">${unclear?`<div class="paper-letter"><span class="eyebrow">SAMPLE DOCUMENT / LOW CLARITY</span><h4 style="margin-top:20px">Riverside Community Hospital</h4><p style="margin-top:26px">Mary Thompson</p><div class="letter-rule"></div><p style="filter:blur(2px);user-select:none" aria-hidden="true">Patient statement<br>Reference number unclear<br>Remaining amount unreadable</p><div class="callout warning"><strong>${t('Amount: unable to read','金额：无法辨认')}</strong><p>${t('This sample needs human review.','此示例需要人工复核。')}</p></div><p class="small muted" style="margin-top:20px">${t('Fictional sample; intentionally unclear.','刻意模糊的虚构示例。')}</p></div>`:letter()}<div class="doc-summary"><span class="eyebrow">${t('YOUR LETTER, EXPLAINED','文件白话解释')}</span><h2>${unclear?t('We need a second look.','我们需要进一步确认。'):t('An amount is left to pay.','有一笔尚未支付的余额。')}</h2><p>${unclear?t('We can see this is a patient statement, but the amount is not readable. A support person can review it with you.','我们能辨认出这是一份患者账单，但无法读出金额。协助人员可以与你一起复核。'):t('The sample statement lists $186 after insurance processing. This is what the letter says, not a new charge from CarePath.','示例账单显示保险处理后仍需支付 $186。这是文件中的内容，并非 CarePath 新收取的费用。')}</p>${!unclear?`<span class="source-tag">${t('SOURCE: PATIENT RESPONSIBILITY · $186.00','依据：PATIENT RESPONSIBILITY · $186.00')}</span>`:''}<div class="callout ${unclear?'warning':''}"><strong>${t('What we don’t know','尚不清楚的事')}</strong><p>${t('The letter does not confirm whether you qualify for assistance. The billing team needs to verify any options.','文件没有确认你是否符合援助条件。任何援助选项均需由账务团队核实。')}</p></div>${button(t('Ask about this explanation','询问这段解释'),'assistant','text','','chat')}</div></div>${!unclear?`<div style="margin-top:24px"><label class="check-row"><input type="checkbox" id="understood" ${state.confirmed?'checked':''}><span>${t('I understand this is a sample amount, not an assistance decision.','我理解这是示例账单金额，不代表援助资格决定。')}<small>${t('You can go back or ask for help at any time.','随时可以返回或请求协助。')}</small></span></label></div>`:`<div class="callout warning"><strong>${t('No answer is better than a guessed answer.','无法确认时，不猜测。')}</strong><p>${t('Choose a clearer sample or ask a person. We’ll keep the context for them.','你可以换成清晰示例或请求真人协助，我们会保留已有上下文。')}</p></div>`}</div>${unclear?`<div class="member-actions">${button(t('Choose another sample','更换示例'),'document','secondary','','back')}${button(t('Ask a person to review','请求真人复核'),'human','primary','','person')}</div>`:memberActions('document',t('Continue to my details','继续补充信息'),'to-details',!state.confirmed)}`;
}
function memberDetails(){
  return `<span class="eyebrow">${t('STEP 3 OF 5 / YOUR DETAILS','第 3 步，共 5 步 / 补充信息')}</span><h1>${t('A few details to get ready.','补充一点信息，做好准备。')}</h1><p class="lead">${t('Use Mary’s fictional profile. These answers help prepare a conversation; they do not determine eligibility.','使用 Mary 的虚构档案。这些回答用于准备咨询，不用于判断资格。')}</p><div class="member-content"><form id="details-form" novalidate><div class="white-panel"><div class="form-grid"><div class="field"><label for="demo-name">${t('First name (sample profile)','名字（示例档案）')}</label><input id="demo-name" value="Mary" readonly aria-describedby="name-help"><small id="name-help">${t('Fictional profile; personal data entry is disabled.','虚构档案，不输入真实个人信息。')}</small></div><div class="field"><label for="household">${t('Who lives with Mary?','Mary 与谁同住？')}</label><select id="household" required aria-describedby="details-error"><option value="">${t('Choose an answer','请选择')}</option><option value="alone" ${state.household==='alone'?'selected':''}>${t('Mary lives alone','Mary 独自居住')}</option><option value="partner" ${state.household==='partner'?'selected':''}>${t('Mary and a partner','Mary 与伴侣同住')}</option><option value="family" ${state.household==='family'?'selected':''}>${t('Mary and family','Mary 与家人同住')}</option></select></div></div><fieldset class="field"><legend>${t('Does Mary have proof of income ready?','Mary 是否准备好了收入证明？')}</legend><div class="radio-group">${[['ready',t('Yes, ready','已准备')],['later',t('Not yet','尚未准备')],['unsure',t('I’m not sure','不确定')]].map(([value,label])=>`<label class="radio-option"><input type="radio" name="income" value="${value}" ${state.income===value?'checked':''} required>${label}</label>`).join('')}</div><small>${t('“Not sure” is a useful answer. You can still prepare your questions.','“不确定”也是有效回答，你仍可继续准备咨询问题。')}</small></fieldset><fieldset class="field"><legend>${t('How would Mary prefer to get help?','Mary 希望通过哪种方式获得帮助？')}</legend><div class="radio-group">${[['phone',t('By phone','电话')],['written',t('In writing','书面沟通')]].map(([v,l])=>`<label class="radio-option"><input type="radio" name="contact" value="${v}" ${state.contact===v?'checked':''}>${l}</label>`).join('')}</div></fieldset><p id="details-error" class="error-message" role="alert"></p><div class="privacy-line">${icon('shield',18)}<span>${t('No income amount or contact details are collected in this prototype.','此原型不收集具体收入金额或联系方式。')}</span></div></div><div class="member-actions">${button(t('Back','返回'),'understand','secondary','type="button"','back')}<button type="submit" class="btn primary">${t('Review my details','核对我的信息')}${icon('arrow',18)}</button></div></form></div>`;
}
function householdLabel(value = state.household){return ({alone:t('Mary lives alone','Mary 独居'),partner:t('Mary and a partner','Mary 与伴侣同住'),family:t('Mary and family','Mary 与家人同住')})[value]||t('Not answered','尚未回答');}
function incomeLabel(value = state.income){return ({ready:t('Ready to bring','已准备好'),later:t('Not yet ready','尚未准备好'),unsure:t('Not sure — ask for help','不确定，需要协助')})[value]||t('Not answered','尚未回答');}
function memberReview(){
  return `<span class="eyebrow">${t('STEP 4 OF 5 / REVIEW','第 4 步，共 5 步 / 核对信息')}</span><h1>${t('Does this look right?','这些信息是否正确？')}</h1><p class="lead">${t('Check Mary’s details before preparing a checklist. You can change any answer.','准备清单前，请核对 Mary 的信息。你可以修改任何回答。')}</p><div class="member-content"><div class="white-panel"><dl class="review-list">${[[t('Sample letter','示例文件'),t('Hospital statement · $186','医院账单 · $186'),'document'],[t('Household','家庭情况'),householdLabel(),'details'],[t('Income document','收入证明'),incomeLabel(),'details'],[t('Help preference','协助方式'),state.contact==='phone'?t('By phone','电话'):t('In writing','书面沟通'),'details']].map(([label,value,dest])=>`<div><dt>${label}</dt><dd>${value}</dd><button class="edit-button" data-action="${dest}" aria-label="${t('Edit','修改')}: ${label}">${t('Edit','修改')}</button></div>`).join('')}</dl><div class="callout"><strong>${t('A checklist, not an application.','这是清单，不是申请。')}</strong><p>${t('CarePath won’t submit anything or contact a hospital. You decide what to do next.','CarePath 不会提交任何内容或联系医院，下一步由你决定。')}</p></div></div><div style="margin-top:20px"><label class="check-row"><input type="checkbox" id="review-confirm" ${state.reviewed?'checked':''}><span>${t('I have checked these sample details.','我已核对这些示例信息。')}<small>${t('This prepares a checklist on your device. It does not authorize sharing with anyone.','这仅在设备上准备清单，不代表授权向任何人共享。')}</small></span></label></div></div>${memberActions('details',t('Prepare my next steps','准备下一步清单'),'prepare',!state.reviewed)}`;
}
function memberNext(){
  return `<div class="success-mark">${icon('check',30)}</div><span class="eyebrow">${t('STEP 5 OF 5 / YOUR NEXT STEPS','第 5 步，共 5 步 / 下一步')}</span><h1>${t('You have a place to start.','现在，知道从哪里开始了。')}</h1><p class="lead">${t('Here’s a simple plan for Mary’s sample letter. Assistance still needs to be verified by the provider.','这是针对 Mary 示例文件准备的计划。是否有援助仍需由服务机构核实。')}</p><div class="member-content"><div class="white-panel"><ol class="next-plan"><li><span class="step-number">1</span><div><h3>${t('Keep the letter nearby.','把文件放在手边。')}</h3><p>${t('Have the statement and any questions ready when speaking with the billing team.','与账务团队联系时，准备好文件和你想问的问题。')}</p></div></li><li><span class="step-number">2</span><div><h3>${t('Ask which support options exist.','咨询有哪些可用的援助。')}</h3><p>${t('“Can someone explain this balance and tell me if financial assistance is available?”','“能否解释这笔余额，并告诉我是否有费用援助可申请？”')}</p></div></li><li><span class="step-number">3</span><div><h3>${state.income==='ready'?t('Bring your documents to the conversation.','咨询时准备好材料。'):t('Ask what documents are needed.','询问需要哪些材料。')}</h3><p>${state.income==='ready'?t('Mary’s demo profile has proof of income ready. The provider must confirm what they actually need.','Mary 的示例档案已有收入证明，但仍由机构确认实际材料要求。'):t('Mary has not confirmed proof of income. Ask the provider what is required before collecting sensitive documents.','Mary 尚未确认收入证明是否齐备。收集敏感材料前，先请机构说明要求。')}</p></div></li></ol><div class="row wrap" style="margin-top:24px">${button(t('Download my checklist','下载下一步清单'),'checklist','secondary','','download')}${button(t('Ask a person to help','请求真人帮助'),'human','text','','person')}</div></div>${state.handoff?`<div class="callout"><strong>${state.partnerStatus==='resolved'?t('Your demo guidance is ready.','模拟咨询指引已准备。'):state.partnerStatus==='in-review'?t('Your demo request is being reviewed.','模拟请求正在复核中。'):t('A demo review request is active.','模拟复核请求已创建。')}</strong><p>${t('You can follow it in the partner workspace, or withdraw it here.','可在合作方工作台查看，也可在此撤回。')}</p><a href="#partners" class="btn text">${t('View partner handoff','查看合作方交接')}${icon('arrow',17)}</a>${button(t('Withdraw request','撤回复核请求'),'withdraw','text')}</div>`:''}<p class="saved-note">${t('Sample progress is saved in this browser only. No application has been submitted.','示例进度仅保存在本浏览器，未提交任何申请。')}</p></div><div class="member-actions">${button(t('Back to review','返回核对'),'review','secondary','','back')}${button(t('Start a new demo','重新体验'),'reset','text')}</div>`;
}
function memberPage(){
  const screens={welcome:memberWelcome,document:memberDocument,understand:memberUnderstand,details:memberDetails,review:memberReview,next:memberNext};
  if(!screens[state.screen]) state.screen='welcome';
  return `${header('prototype')}<main id="main" tabindex="-1" class="product-body ${state.large?'large':''}">${productHeader()}<div class="member-layout">${memberSidebar()}<section class="member-main" aria-label="Member flow">${screens[state.screen]()}</section></div><button class="btn primary assistant-button" data-action="assistant">${icon('chat',18)}${t('Your AI helper','AI 帮手')}</button></main>`;
}

function partnerCases(){
  const shared=state.handoffSnapshot || state;
  const base=[{id:'CP-1024',name:'Mary Thompson',doc:shared.doc==='unclear'?t('Hard-to-read statement','模糊账单'):t('Patient statement','患者账单'),status:state.handoff?state.partnerStatus:'sample',reason:shared.doc==='unclear'?t('Amount could not be read','金额无法辨认'):t('Assistance questions','费用援助咨询')},
    {id:'CP-1023',name:'Robert Ellis',doc:t('Patient statement','患者账单'),status:'in-review',reason:t('Document requirements','材料要求')},
    {id:'CP-1022',name:'Elaine Brooks',doc:t('Billing letter','费用信件'),status:'resolved',reason:t('Next steps explained','已解释下一步')}];
  return base.filter(c=>(state.partnerFilter==='all'||state.partnerFilter===c.status)&&(`${c.name} ${c.id}`.toLowerCase().includes(state.search.toLowerCase())));
}
function statusLabel(status){return ({sample:t('Demo case','示例案例'),'needs-review':t('Needs review','待复核'),'in-review':t('In review','复核中'),resolved:t('Guidance ready','指引已准备')})[status]||status;}
function partnerDetail(){
  const mary=state.selectedCase==='CP-1024';
  const shared=state.handoffSnapshot || state;
  return `<div class="case-detail white-panel"><div class="detail-header"><div><span class="eyebrow">${esc(state.selectedCase)} / ${t('DEMO CASE','模拟案例')}</span><h2 style="margin-top:10px">${mary?'Mary Thompson':state.selectedCase==='CP-1023'?'Robert Ellis':'Elaine Brooks'}</h2></div>${button(t('Close case','关闭案例'),'close-case','secondary')}</div><div class="detail-columns"><div><span class="eyebrow">${t('Context carried from the member','来自会员端的上下文')}</span><div class="extract-row"><span>${t('Document','文件')}</span><strong>${mary&&shared.doc==='unclear'?t('Unreadable amount','金额不清'):t('Sample patient statement','示例患者账单')}</strong></div><div class="extract-row"><span>${t('Household','家庭情况')}</span><strong>${mary?householdLabel(shared.household):t('Not confirmed','尚未确认')}</strong></div><div class="extract-row"><span>${t('Income proof','收入证明')}</span><strong>${mary?incomeLabel(shared.income):t('Not confirmed','尚未确认')}</strong></div><div class="extract-row"><span>${t('Sharing permission','共享授权')}</span><strong>${mary&&state.handoff?t('Granted for this review','已授权本次复核'):t('Sample only','仅示例')}</strong></div><div class="callout warning"><strong>${t('Human verification required','需要人工核实')}</strong><p>${t('Review the source with the member. Do not infer eligibility from the AI summary or sample amount.','与会员对照原始文件。不可依据 AI 摘要或示例金额推断资格。')}</p></div><div class="row wrap" style="margin-top:20px">${button(t('View source','查看原文'),'source','secondary','','file')}${mary&&state.handoff&&state.partnerStatus==='needs-review'?button(t('Begin review','开始复核'),'begin-review','primary'):''}${mary&&state.handoff&&state.partnerStatus==='in-review'?button(t('Prepare guidance','准备咨询指引'),'resolve','primary'):''}</div>${mary&&!state.handoff?`<p class="small muted" style="margin-top:16px">${t('A member must authorize a handoff before this demo case can be acted on.','会员授权交接后，才可操作此模拟案例。')}</p><a class="btn text" href="#prototype">${t('Try the member handoff','体验会员端交接')}${icon('arrow',17)}</a>`:''}</div><div><span class="eyebrow">${t('Case activity','案例活动')}</span><ol class="timeline"><li><time>DEMO / 09:41</time>${t('Sample document selected.','已选择示例文件。')}</li><li><time>DEMO / 09:43</time>${t('AI flagged information for verification.','AI 标明需要核实的信息。')}</li>${mary&&state.handoff?`<li><time>DEMO / REQUESTED</time>${t('Member consented to sharing this case for review.','会员已授权共享本案例以供复核。')}</li>`:''}${mary&&state.partnerStatus!=='needs-review'&&state.handoff?`<li><time>DEMO / IN REVIEW</time>${t('Support person began reviewing the source.','协助人员开始核对原文。')}</li>`:''}${mary&&state.partnerStatus==='resolved'&&state.handoff?`<li><time>DEMO / GUIDANCE READY</time>${t('Questions prepared. No real contact or application submission.','咨询问题已整理，未真实联系机构或提交申请。')}</li>`:''}</ol><div class="callout"><strong>${t('Review boundary','复核边界')}</strong><p>${t('This demo changes local case status only. It sends no message and assigns no real support worker.','此演示仅更新本地案例状态，不发送消息，也不会分配真实工作人员。')}</p></div></div></div></div>`;
}
function partnerPage(){
  const cases=partnerCases();
  return `${header('partners')}<main id="main" tabindex="-1" class="product-body">${productHeader(true)}<div class="partner-layout"><aside class="partner-side"><a href="#partners">${icon('folder',18)}${t('Case queue','案例队列')}</a><p>${t('A shared view for the moments that need a person.','为需要真人介入的时刻，提供连续的上下文。')}</p></aside><section class="partner-main"><div class="workspace-heading"><div class="row between wrap"><span class="eyebrow">${t('SUPPORT WORKSPACE','支持工作台')}</span>${pill(t('Fictional workspace','虚构工作台'),'dot')}</div><h1 style="margin-top:18px">${t('Cases to review','待复核案例')}</h1><p>${t('Review what’s uncertain. Help each person move forward.','核实不确定的信息，帮助每位用户继续前进。')}</p></div><div class="workspace-stats"><div><strong>${state.handoff&&state.partnerStatus==='needs-review'?'1':'0'}</strong><span>${t('New member requests','新会员请求')}</span></div><div><strong>${state.handoff&&state.partnerStatus==='in-review'?'2':'1'}</strong><span>${t('In review · sample','复核中 · 示例')}</span></div><div><strong>${state.handoff&&state.partnerStatus==='resolved'?'2':'1'}</strong><span>${t('Guidance ready · sample','指引已准备 · 示例')}</span></div></div><div class="filters"><div class="tabs" role="group" aria-label="Filter cases">${[['all',t('All cases','全部案例')],['needs-review',t('Needs review','待复核')],['in-review',t('In review','复核中')]].map(([v,l])=>`<button class="tab ${state.partnerFilter===v?'active':''}" data-filter="${v}" aria-pressed="${state.partnerFilter===v}">${l}</button>`).join('')}</div><label><span class="sr-only">${t('Search cases','搜索案例')}</span><input class="search" id="case-search" placeholder="${t('Search name or case ID','搜索姓名或案例编号')}" value="${esc(state.search)}"></label></div><div id="case-results">${caseRows(cases)}</div>${state.selectedCase?partnerDetail():`<div class="callout"><strong>${t('Consented handoff','授权后的人工交接')}</strong><p>${t('A member-authorized request appears in the queue with the confirmed information and the question requiring review.','会员授权后的请求进入案例队列，保留已确认信息与待核对问题。')}</p><a class="btn text" href="#prototype">${t('Open member prototype','打开会员原型')}${icon('arrow',17)}</a></div>`}</section></div></main>`;
}
function caseRows(cases){
  if(!cases.length)return `<div class="empty-state"><span class="icon-mark">${icon('folder',22)}</span><h3 style="margin-top:20px">${t('No cases match.','没有匹配的案例。')}</h3><p class="small muted" style="margin-top:12px">${t('Try another name or clear the filter.','尝试其他姓名或清除筛选。')}</p>${button(t('Clear filters','清除筛选'),'clear-filter','text')}</div>`;
  return `<table class="case-table"><thead><tr><th>${t('Member','会员')}</th><th>${t('Status','状态')}</th><th>${t('Review focus','复核重点')}</th><th><span class="sr-only">${t('Open case','打开案例')}</span></th></tr></thead><tbody>${cases.map(c=>`<tr><td><span class="person-name">${c.name}</span><span class="person-meta">${c.id} · ${c.doc}</span></td><td>${pill(statusLabel(c.status),c.status==='needs-review'?'orange':'green')}</td><td>${c.reason}</td><td><button class="btn secondary" data-case="${c.id}" aria-label="${t('Open case for','打开案例：')} ${c.name}">${t('Review','查看')}${icon('arrow',15)}</button></td></tr>`).join('')}</tbody></table>`;
}

function systemPage(){
  return `${header('system')}<main id="main" tabindex="-1" class="shell"><section class="system-header"><div class="row between wrap"><span class="eyebrow">CAREPATH / FOUNDATIONS & COMPONENTS</span>${pill('v1.0 · Live components','dot')}</div><h1>${t('Clarity, by design.','让清晰，成为系统。')}</h1><p>${t('A small, working design system for a human-supported AI product. These are the same tokens and components used in the member and partner experiences.','为人工协作型 AI 产品构建的小型可运行设计系统。以下令牌与组件直接用于会员端和合作方端。')}</p></section><div class="system-layout"><nav class="system-nav" aria-label="Design system sections">${[['color',t('01 Color & semantics','01 配色与语义')],['type',t('02 Typography','02 字体')],['space',t('03 Spacing','03 间距')],['components',t('04 Components','04 组件')],['accessibility',t('05 Accessibility','05 无障碍')],['logic',t('06 Interaction logic','06 交互逻辑')]].map(([id,l])=>`<a href="#ds-${id}">${l}</a>`).join('')}</nav><div>
    <section class="system-section" id="ds-color"><span class="eyebrow">01 / COLOR</span><h2 style="margin-top:12px">${t('Meaning before decoration.','颜色，首先表达意义。')}</h2><p>${t('Primitive → semantic → component: pine → action.primary → button.primary.background. Status always includes a label, not color alone.','原始值 → 语义 → 组件：松绿色 → 主要操作 → 主要按钮背景。状态始终搭配文字，不只依赖颜色。')}</p><div class="token-grid">${[['pine','Action / primary','#21483E','--pine'],['sage','Surface / supportive','#E6EDE2','--sage'],['paper','Surface / canvas','#F7F5EF','--paper'],['ink','Text / primary','#233B34','--ink'],['white','Surface / raised','#FFFEFB','--white'],['orange','Attention / warm','#A34D30','--orange'],['error','Feedback / error','#A03029','--error'],['focus','Focus / ring','#A34D30','--focus']].map(([cl,n,hex,key])=>`<div class="token"><div class="token-color ${cl}"></div><div class="token-info">${n}<code>${hex} · ${key}</code></div></div>`).join('')}</div><div class="contrast-result" id="contrast-ratio"></div><p class="small muted">${t('Measured from the actual CSS colors: primary button text on pine. This is a component check, not a full accessibility audit.','根据实际 CSS 颜色计算：松绿色按钮上的文字。这是组件级检查，不代表完整无障碍审核。')}</p>${button(t('Download design tokens','下载设计令牌'),'tokens','text','','download')}</section>
    <section class="system-section" id="ds-type"><span class="eyebrow">02 / TYPOGRAPHY</span><h2 style="margin-top:12px">${t('Warm voice. Readable words.','温暖的声音，易读的文字。')}</h2><div class="scale-row"><code>DISPLAY / 64–116</code><span class="display">A clearer path.</span></div><div class="scale-row"><code>HEADING / 32</code><span class="product-title">One step at a time.</span></div><div class="scale-row"><code>BODY / 18 · 1.6</code><span>Let’s make sense of your letter.</span></div><div class="scale-row"><code>LABEL / 12</code><span class="eyebrow">YOUR LETTER, EXPLAINED</span></div><p>${t('Libre Caslon Display for editorial moments, DM Sans for product controls, and DM Mono for navigation metadata. Fallbacks keep the product usable if fonts cannot load.','Libre Caslon Display 用于编辑式标题，DM Sans 用于产品正文和控件，DM Mono 用于索引信息。网络字体失败时使用系统回退字体。')}</p></section>
    <section class="system-section" id="ds-space"><span class="eyebrow">03 / SPACE & GEOMETRY</span><h2 style="margin-top:12px">${t('Room to understand.','给理解，留出空间。')}</h2><div class="spacing-demo">${[4,8,12,16,24,32,48,64].map(v=>`<div class="space-item"><div class="space-bar s${v}"></div>${v}px</div>`).join('')}</div><p>${t('A 4 / 8 px rhythm, 8 px control radius, 16 px panel radius, and 48 px minimum primary touch targets. Structure comes from hairlines and tonal surfaces.','4 / 8 px 间距节奏，8 px 控件圆角，16 px 容器圆角，主要操作触控区域至少 48 px。用细分隔线与浅色面建立层级。')}</p></section>
    <section class="system-section" id="ds-components"><span class="eyebrow">04 / LIVE COMPONENTS</span><h2 style="margin-top:12px">${t('A language of small actions.','用小而明确的操作交流。')}</h2><div class="component-stage"><div class="component-caption">BUTTON / PRIMARY · SECONDARY · DISABLED</div><div class="row wrap">${button(t('Continue','继续'),'ds-continue','primary','','arrow')}${button(t('Back','返回'),'ds-back','secondary','','back')}${button(t('Not available','暂不可用'),'none','primary','disabled')}</div></div><div class="system-components"><div class="component-stage"><div class="component-caption">FORM / REQUIRED · ERROR · RECOVERY</div><form id="ds-form" novalidate><div class="field"><label for="ds-name">${t('Sample first name','示例名字')}</label><input id="ds-name" placeholder="Mary" aria-describedby="ds-error" ${state.dsError?'aria-invalid="true"':''}><small>${t('Try continuing with an empty field.','尝试不填任何内容后继续。')}</small></div><p class="error-message" id="ds-error" role="alert">${state.dsError?t('Enter a sample name to continue.','请输入一个示例名字后继续。'):''}</p><button type="submit" class="btn secondary">${t('Check field','检查字段')}</button></form></div><div class="component-stage"><div class="component-caption">FEEDBACK / LABEL + COLOR</div><div class="status-list">${pill(t('Ready to continue','可以继续'))}${pill(t('Needs review','需要复核'),'orange')}${pill(t('Not submitted','尚未提交'),'dot')}</div><div class="callout error"><strong>${t('We couldn’t read the amount.','无法辨认金额。')}</strong><p>${t('Choose a clearer sample or ask a person to review it.','请选择更清晰的示例，或请求真人复核。')}</p></div></div></div><div class="component-stage"><div class="component-caption">PERMISSION / EXPLICIT, SCOPED, REVERSIBLE</div><label class="check-row"><input type="checkbox" id="ds-consent"><span>${t('Share this sample case with a support person.','将此示例案例共享给协助人员。')}<small>${t('Includes the sample letter, confirmed details, and your question.','包含示例文件、已确认信息和你的问题。')}</small></span></label><p class="small muted" id="ds-consent-status" style="margin-top:14px">${t('Not selected. Nothing is shared.','尚未选择，不共享任何内容。')}</p></div></section>
    <section class="system-section" id="ds-accessibility"><span class="eyebrow">05 / ACCESSIBILITY</span><h2 style="margin-top:12px">${t('Confidence includes access.','可访问，才谈得上安心。')}</h2><div class="a11y-grid">${[
      [t('Visible keyboard focus','可见的键盘焦点'),t('3 px clay focus ring. Native links, buttons, labels, and dialogs. Escape closes the dialog and returns focus to its trigger.','3 px 陶色焦点框，使用原生链接、按钮、标签和对话框。Escape 关闭对话框并将焦点返回触发控件。')],
      [t('Readable by default','默认易读'),t('18 px body text, a 21 px larger-text mode, responsive reflow, and named actions instead of unlabeled icons.','18 px 正文、21 px 大字模式、响应式重排，并使用明确文字操作代替无标签图标。')],
      [t('Errors that explain recovery','错误说明恢复方法'),t('Name the problem in text, preserve previous answers, and focus the first unanswered field after validation.','用文字说明问题，保留已选回答，并在验证后聚焦首个未完成字段。')],
      [t('Motion with restraint','克制的动效'),t('No automatic animation. Short feedback transitions respect prefers-reduced-motion. Test with actual users and assistive technology next.','不使用自动播放动画。短反馈过渡尊重减少动态效果偏好，后续需用真实用户与辅助技术验证。')]
    ].map(([h,p])=>`<div class="a11y-item"><strong>${h}</strong><p>${p}</p></div>`).join('')}</div></section>
    <section class="system-section" id="ds-logic"><span class="eyebrow">06 / INTERACTION CONTRACT</span><h2 style="margin-top:12px">${t('Every state has a next step.','每种状态，都有可走的下一步。')}</h2><div class="flow-map"><ol><li><strong>Document → Understand</strong> / ${t('A sample must be selected. A processing state is announced.','先选择示例，再播报处理中状态。')}</li><li><strong>Understand → Details</strong> / ${t('Confirm understanding; unreadable samples branch to human review.','确认理解后继续，模糊示例分支转交人工。')}</li><li><strong>Details → Review</strong> / ${t('Household and document readiness required. “Not sure” remains valid.','家庭情况与材料准备度必答，“不确定”为有效选项。')}</li><li><strong>Review → Checklist</strong> / ${t('Explicitly check the details. No external submission occurs.','明确勾选核对，不发生对外提交。')}</li><li><strong>Any state → Human support</strong> / ${t('Review sharing scope, consent, then create a local demo case. Revocation removes the active request.','查看共享范围、授权后创建本地模拟案例；撤回会取消活跃请求。')}</li></ol></div><p>${t('Draft scope: sample selection, fixed-profile choices, and display settings are stored in this browser. No file contents, free-form questions, real contact details, or credentials are collected.','草稿范围：在本浏览器保存示例选择、固定档案选项与显示偏好。不收集文件内容、自由文本问题、真实联系方式或凭据。')}</p><div class="row wrap" style="margin-top:24px"><a class="btn primary" href="#prototype">${t('Test the interaction','验证实际交互')}${icon('arrow',18)}</a>${button(t('Reset all demo progress','重置所有示例进度'),'reset-all','text')}</div></section>
    </div></div>${footer()}</main>`;
}

function render(options = {}) {
  const active=route();
  document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';
  document.title=`CarePath — ${({case:'Case study',prototype:'Member prototype',partners:'Partner workspace',system:'Design system'})[active]}`;
  app.innerHTML=({case:casePage,prototype:memberPage,partners:partnerPage,system:systemPage})[active]();
  bind();
  if(active==='system') updateContrast();
  save();
  if(options.top) window.scrollTo({top:0,behavior:'instant'});
  if(options.focus){const h=$('main h1'); if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
}
function goScreen(screen){ state.screen=screen; render({top:true,focus:true}); }
function notify(message){
  $('#live').textContent=message;
  document.querySelector('.toast')?.remove();
  const node=document.createElement('div'); node.className='toast'; node.textContent=message; document.body.append(node);
  setTimeout(()=>node.remove(),3400);
}
function closeDialog(){ if(dialog.open)dialog.close(); dialogKind=''; if(priorFocus?.isConnected)priorFocus.focus(); else {const heading=$('main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}} }
function openDialog(kind, custom = ''){
  if(!dialog.open)priorFocus=document.activeElement;
  dialogKind=kind;
  let title='',body='';
  if(kind==='human'){
    title=t('A person can help.','可以请真人帮忙。');
    body=state.handoff?`<div class="success-mark">${icon('check',28)}</div><h3>${t('Your demo request is active.','你的模拟请求已生效。')}</h3><p style="margin-top:18px">${t('This fictional request is available in the support workspace. No real support person has been contacted.','模拟请求可在支持工作台查看，未联系真实工作人员。')}</p><a class="btn primary" href="#partners" data-close-dialog>${t('View partner workspace','查看合作方工作台')}${icon('arrow',18)}</a>${button(t('Withdraw request','撤回请求'),'withdraw','text')}`:
    `<p>${t('In this demo, a support person receives a sample case in the partner workspace. Nothing is sent to a real organization.','此演示会在合作方工作台创建示例案例，不会发送给真实机构。')}</p><div class="white-panel"><span class="eyebrow">${t('WHAT WOULD BE SHARED','将共享的内容')}</span><ul class="small"><li>${t('The fictional sample letter','虚构示例文件')}</li><li>${t('Confirmed profile choices, if available','已确认的档案选项（如有）')}</li><li>${state.doc==='unclear'?t('Question: “Can you help read this amount?”','问题：“能帮我辨认这个金额吗？”'):t('Question: “What should I ask the billing team?”','问题：“我该向账务团队询问什么？”')}</li></ul></div><label class="check-row" style="margin-top:20px"><input type="checkbox" id="handoff-consent"><span>${t('I agree to share this sample case for review.','我同意共享此示例案例以供复核。')}<small>${t('Only for this request. You can withdraw it later.','仅限本次请求，之后可以撤回。')}</small></span></label><p class="error-message" id="handoff-error" role="alert"></p><div class="dialog-actions">${button(t('Not now','暂时不用'),'close','secondary')}${button(t('Create demo request','创建模拟请求'),'send-handoff','primary','','arrow')}</div>`;
  } else if(kind==='assistant'){
    title=t('Your AI helper','你的 AI 帮手');
    body=`<p class="small">${t('Scripted demo helper · Not a live AI or medical advice.','脚本化示例助手 · 非实时 AI，不提供医疗建议。')}</p><div class="chat-thread" id="chat-thread" aria-live="polite"><div class="chat-msg"><small>CAREPATH HELPER</small>${t('I can help explain the sample and prepare questions. What would you like to understand?','我可以解释示例并准备咨询问题。你想了解什么？')}</div></div><div>${[['amount',t('Does $186 mean I qualify for help?','$186 是否代表我符合援助条件？')],['unknown',t('What if I don’t have every document?','如果我没有准备好全部材料呢？')],['person',t('I’d rather talk to a person.','我更想找真人帮忙。')]].map(([key,label])=>`<button class="chat-choice" data-chat="${key}">${label}${icon('arrow',16)}</button>`).join('')}</div>`;
  } else if(kind==='source'){
    title=t('Source document','原始文件');body=(state.selectedCase==='CP-1024' ? (state.handoffSnapshot?.doc || state.doc) : 'clear')==='unclear' ? unclearLetter() : letter();
  } else if(kind==='pause'){
    title=t('A good place to pause.','随时可以暂停。');
    body=`<div class="success-mark">${icon('check',26)}</div><p>${t('Your sample progress is saved in this browser. Come back to the member prototype to continue. No information has been sent.','你的示例进度已保存在本浏览器。回来后可继续，未向外发送任何信息。')}</p>${button(t('Return to case study','返回作品集案例'),'pause-exit','primary')}`;
  } else if(kind==='reset'){
    title=t('Start a fresh demo?','开始新的演示？');body=`<p>${t('This clears the sample letter, profile choices, and demo review request in this browser. Your language and text size stay the same.','将清除本浏览器的示例文件、档案选项和模拟复核请求，保留语言与字号设置。')}</p><div class="dialog-actions">${button(t('Keep progress','保留进度'),'close','secondary')}${button(t('Reset demo','重置演示'),'confirm-reset','primary')}</div>`;
  } else if(kind==='guidance'){
    title=t('Prepare guidance','准备咨询指引');body=`<p>${t('Confirm the demo review has checked the source. This marks guidance as ready; it does not contact the member or approve assistance.','确认本次模拟复核已查看原文。此操作仅标记指引已准备，不会联系会员或批准援助。')}</p><div class="callout"><strong>${t('Suggested question list','建议咨询问题')}</strong><p>${t('What does this balance represent? Is assistance available? Which documents are required?','这笔余额代表什么？是否有援助可申请？需要哪些材料？')}</p></div><label class="check-row" style="margin-top:20px"><input type="checkbox" id="source-reviewed"><span>${t('I reviewed the sample source and its unknowns.','我已核对示例原文与尚不确定的信息。')}</span></label><p class="error-message" id="guidance-error" role="alert"></p>${button(t('Mark guidance ready','标记指引已准备'),'confirm-guidance','primary')}`;
  }
  dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close-btn" data-action="close" aria-label="${t('Close dialog','关闭对话框')}">${icon('close',20)}</button></div><div class="dialog-body">${custom||body}</div>`;
  bind(dialog);
  if(!dialog.open)dialog.showModal();
}
dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});

const actions={
  lang(){state.lang=state.lang==='en'?'zh':'en';render();},
  font(){state.large=!state.large;render();notify(t(state.large?'Larger text is on.':'Standard text is on.',state.large?'已开启大字模式。':'已恢复标准字号。'));},
  start(){goScreen('document');},welcome(){goScreen('welcome');},document(){goScreen('document');},understand(){goScreen('understand');},details(){goScreen('details');},review(){state.reviewed=false;goScreen('review');},
  resume(){goScreen(state.prepared?'next':state.confirmed?'details':'understand');},
  'select-clear'(){state.doc='clear';state.confirmed=false;state.prepared=false;state.reviewed=false;render();},
  'select-unclear'(){state.doc='unclear';state.confirmed=false;state.prepared=false;state.reviewed=false;render();},
  explain(el){
    if(!state.doc)return;
    el.disabled=true;el.innerHTML=`${icon('clock',18)}${t('Reading the sample…','正在读取示例……')}`;
    $('#live').textContent=t('Reading the sample document.','正在读取示例文件。');
    busyTimer=setTimeout(()=>{if(route()==='prototype'){goScreen('understand');$('#live').textContent=t('Sample explanation is ready.','示例解释已准备好。');}},650);
  },
  'to-details'(){if(state.confirmed)goScreen('details');},
  prepare(){if(!state.reviewed)return;state.prepared=true;goScreen('next');},
  human(){openDialog('human');},assistant(){openDialog('assistant');},pause(){save();openDialog('pause');},source(){openDialog('source');},close(){closeDialog();},
  'pause-exit'(){closeDialog();location.hash='case';},
  'send-handoff'(){
    if(!$('#handoff-consent')?.checked){$('#handoff-error').textContent=t('Choose whether to share this sample case before continuing.','请先确认是否授权共享此示例案例。');$('#handoff-consent').focus();return;}
    if(!state.doc)state.doc='clear';
    state.consent=true;state.handoff=true;state.handoffSnapshot={doc:state.doc,household:state.household,income:state.income,contact:state.contact};state.partnerStatus='needs-review';save();
    render();openDialog('human');$('#live').textContent=t('Demo review request created.','已创建模拟复核请求。');
  },
  withdraw(){state.handoff=false;state.handoffSnapshot=null;state.consent=false;state.partnerStatus='needs-review';state.selectedCase='';save();closeDialog();render();notify(t('Demo request withdrawn. The partner no longer has an active request.','已撤回模拟请求，合作方不再有活跃请求。'));},
  reset(){openDialog('reset');},'reset-all'(){openDialog('reset');},
  'confirm-reset'(){const {lang,large}=state;Object.assign(state,{lang,large,screen:'welcome',doc:'',confirmed:false,household:'',income:'',contact:'phone',consent:false,prepared:false,handoff:false,handoffSnapshot:null,partnerStatus:'needs-review',selectedCase:'',reviewed:false});save();closeDialog();render({top:true});notify(t('Demo progress reset.','示例进度已重置。'));},
  'close-case'(){state.selectedCase='';render();},
  'clear-filter'(){state.search='';state.partnerFilter='all';render();},
  'begin-review'(){if(!state.handoff)return;state.partnerStatus='in-review';render();notify(t('Demo case is now in review.','模拟案例现已进入复核。'));},
  resolve(){if(state.handoff)openDialog('guidance');},
  'confirm-guidance'(){if(!$('#source-reviewed').checked){$('#guidance-error').textContent=t('Review the source before marking guidance ready.','请先核对原始文件，再标记指引已准备。');$('#source-reviewed').focus();return;}state.partnerStatus='resolved';save();closeDialog();render();notify(t('Demo guidance marked ready. No message was sent.','模拟指引已准备，未发送任何消息。'));},
  checklist(){download('carepath-mary-checklist.txt',`CarePath — Sample next-step checklist\nFICTIONAL DEMO. No application submitted. No eligibility determination.\n\n1. Keep the sample hospital statement nearby.\n2. Ask the billing team: What does this balance represent? Is assistance available?\n3. Ask which documents are required.\n\nSample patient responsibility shown: $186.00 (not a qualification result).\nHousehold: ${state.household || 'not confirmed'}\nIncome proof: ${state.income || 'not confirmed'}\nHelp preference: ${state.contact}\n\nAll people and organizations are fictional. Do not use this checklist as a real assistance decision.\n`,'text/plain');},
  tokens(){download('carepath-design-tokens.json',JSON.stringify({$description:'CarePath concept v1.0. Shared CSS primitives and semantic aliases.',$schema:'https://www.designtokens.org/schemas/2025.10/format.json',color:{pine:{$type:'color',$value:{colorSpace:'srgb',components:[33/255,72/255,62/255],alpha:1}},paper:{$type:'color',$value:{colorSpace:'srgb',components:[247/255,245/255,239/255],alpha:1}},ink:{$type:'color',$value:{colorSpace:'srgb',components:[35/255,59/255,52/255],alpha:1}},sage:{$type:'color',$value:{colorSpace:'srgb',components:[230/255,237/255,226/255],alpha:1}},clay:{$type:'color',$value:{colorSpace:'srgb',components:[163/255,77/255,48/255],alpha:1}}},semantic:{action:{primary:{$type:'color',$value:'{color.pine}'}},text:{primary:{$type:'color',$value:'{color.ink}'}},surface:{canvas:{$type:'color',$value:'{color.paper}'},supportive:{$type:'color',$value:'{color.sage}'}}},spacing:Object.fromEntries([4,8,12,16,24,32,48,64,96,144].map(v=>[String(v),{$type:'dimension',$value:{value:v,unit:'px'}}])),size:{target:{$type:'dimension',$value:{value:48,unit:'px'}}}},null,2),'application/json');},
  'research-download'(){download('carepath-research-plan.txt',`CAREPATH — RESEARCH PLAN / NOT YET CONDUCTED\n\nPurpose\nTest comprehension, control, recovery, and trust in an AI-assisted document-preparation flow.\n\nParticipants\nRecruit 3–5 older adults or caregivers with varied digital confidence. Explain that this is a concept, not real benefits assistance. Do not collect real medical records. Obtain consent before recording.\n\nInterview prompts\n1. Tell me about the last confusing official letter you received.\n2. How did you decide what to do next?\n3. Who do you turn to for help?\n4. What would make you hesitate to share a document?\n\nTasks using fictional samples\n1. Explain what the sample statement says, in your own words.\n2. Find the source of the amount. Does it mean assistance is approved?\n3. Complete the sample profile, then correct one answer.\n4. Try the unclear sample and request a person.\n5. Explain what will be shared, then withdraw the request.\n\nObserve\nTask completion, misunderstanding, help requests, recovery, and confidence before/after. Do not use leading questions. Establish a baseline before defining success thresholds.\n\nEvidence log columns\nParticipant code | Task | Observation | Verbatim quote (with consent) | Interpretation | Severity | Proposed change | Retest result\n\nReporting\nSeparate assumptions from findings. Report sample size and limitations. No invented personas, quotes, results, or impact metrics.\n`,'text/plain');},
  'ds-continue'(){notify(t('Primary action: clear feedback after a deliberate step.','主要操作：完成明确动作后，提供清晰反馈。'));},'ds-back'(){notify(t('Back action: preserve answers and let the person recover.','返回操作：保留回答，让用户可以恢复与修改。'));}
};
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(t('Download prepared.','下载文件已准备。'));}
function bind(root = app){
  root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>actions[el.dataset.action]?.(el)));
  root.querySelectorAll('[data-close-dialog]').forEach(el=>el.addEventListener('click',closeDialog));
  root.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>{state.partnerFilter=el.dataset.filter;render();}));
  root.querySelectorAll('[data-case]').forEach(el=>el.addEventListener('click',()=>{state.selectedCase=el.dataset.case;render();$('.case-detail')?.scrollIntoView({behavior:'smooth',block:'start'});}));
  $('#understood',root)?.addEventListener('change',e=>{state.confirmed=e.target.checked;const next=$('[data-action="to-details"]');if(next)next.disabled=!state.confirmed;save();});
  $('#review-confirm',root)?.addEventListener('change',e=>{state.reviewed=e.target.checked;$('[data-action="prepare"]').disabled=!state.reviewed;});
  $('#household',root)?.addEventListener('change',e=>{state.household=e.target.value;state.prepared=false;e.target.removeAttribute('aria-invalid');$('#details-error').textContent='';save();});
  root.querySelectorAll('[name="income"]').forEach(el=>el.addEventListener('change',e=>{state.income=e.target.value;state.prepared=false;$('#details-error').textContent='';save();}));
  root.querySelectorAll('[name="contact"]').forEach(el=>el.addEventListener('change',e=>{state.contact=e.target.value;save();}));
  $('#details-form',root)?.addEventListener('submit',e=>{
    e.preventDefault();const error=$('#details-error');
    if(!state.household){error.textContent=t('Choose who lives with Mary to continue.','请选择 Mary 与谁同住后继续。');$('#household').setAttribute('aria-invalid','true');$('#household').focus();return;}
    if(!state.income){error.textContent=t('Choose whether Mary has proof of income. “Not sure” is okay.','请选择 Mary 是否准备好收入证明，也可以选择“不确定”。');$('[name="income"]').focus();return;}
    state.reviewed=false;goScreen('review');
  });
  $('#case-search',root)?.addEventListener('input',e=>{state.search=e.target.value;$('#case-results').innerHTML=caseRows(partnerCases());bind($('#case-results'));});
  $('#ds-form',root)?.addEventListener('submit',e=>{e.preventDefault();const field=$('#ds-name');if(!field.value.trim()){state.dsError=true;field.setAttribute('aria-invalid','true');$('#ds-error').textContent=t('Enter a sample name to continue.','请输入一个示例名字后继续。');field.focus();}else{state.dsError=false;field.removeAttribute('aria-invalid');$('#ds-error').textContent='';notify(t('Sample field accepted. Nothing was saved.','示例字段已通过，未保存内容。'));}});
  $('#ds-consent',root)?.addEventListener('change',e=>{$('#ds-consent-status').textContent=e.target.checked?t('Selected for this component demo. No case was shared.','已在此组件演示中勾选，未实际共享案例。'):t('Not selected. Nothing is shared.','尚未选择，不共享任何内容。');});
  root.querySelectorAll('[data-chat]').forEach(el=>el.addEventListener('click',()=>chatReply(el.dataset.chat,el.textContent)));
}
function chatReply(key,question){
  if(key==='person'){openDialog('human');return;}
  const reply=key==='amount'?t('No. The $186 is only the amount printed on the fictional statement. It does not tell us whether Mary qualifies for help. The billing team needs to explain the balance and verify any support options.','不是。$186 只是虚构账单上的金额，不代表 Mary 有资格获得援助。账务团队需要解释余额并核实可用的援助选项。'):t('You can choose “not sure” and continue. The checklist will include a question about required documents. A person can help verify what is needed before you collect or share anything sensitive.','你可以选择“不确定”后继续。清单会包含关于所需材料的问题。收集或共享敏感信息前，可以请真人核实实际要求。');
  $('#chat-thread').insertAdjacentHTML('beforeend',`<div class="chat-msg user"><small>${t('YOU','你')}</small>${esc(question)}</div><div class="chat-msg"><small>CAREPATH HELPER</small>${reply}</div>`);
  $('#chat-thread').scrollTop=$('#chat-thread').scrollHeight;
}
function updateContrast(){
  if(!$('#contrast-ratio'))return;
  const css=getComputedStyle(document.documentElement);
  function lum(hex){const rgb=hex.trim().replace('#','').match(/../g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];}
  const a=lum(css.getPropertyValue('--white')),b=lum(css.getPropertyValue('--pine'));
  $('#contrast-ratio').textContent=`${((Math.max(a,b)+.05)/(Math.min(a,b)+.05)).toFixed(2)}:1 ${t('contrast / primary action','对比度 / 主要操作')}`;
}
const caseAnchors=['caregiver-story','problem','overview','principles','workflow','safety','foundations','research'];
window.addEventListener('hashchange',()=>{
  clearTimeout(busyTimer);
  const id=location.hash.slice(1);
  if(caseAnchors.includes(id)){if(!$(`#${id}`))render();requestAnimationFrame(()=>$(`#${id}`)?.scrollIntoView());return;}
  if(id.startsWith('ds-')){if(!$('#ds-color')){app.innerHTML=systemPage();bind();updateContrast();}requestAnimationFrame(()=>$(`#${id}`)?.scrollIntoView());return;}
  closeDialog();render({top:true});
});
